        accepting_states = [n-1]

        for q in states:
            for a in alphabet:
                next_q = random.choice(states)
                while next_q == q:
                    next_q = random.choice(states)
                transition_table[q][a] = next_q

        return {
            'states': states,
            'alphabet': alphabet,
            'transition_table': transition_table,
            'start_state': start_state,
            'accepting_states': accepting_states
        }

